mapper.select:
SELECT wr.id, wr.user_id AS userId, wr.record_date AS recordDate, wr.duration, wr.sets_count AS setsCount, wr.reps, wr.calories_burned AS caloriesBurned, wr.exercise_id AS exerciseId, wr.plan_id AS planId, e.exercise_name AS exerciseName, e.muscle_group AS muscleGroup, e.difficulty, e.calories_per_minute AS caloriesPerMinute, wp.plan_name AS planName, wp.plan_goal AS planGoal FROM workout_records wr LEFT JOIN exercises e ON wr.exercise_id = e.id LEFT JOIN workout_plans wp ON wr.plan_id = wp.id WHERE wr.user_id = #{userId}
AND wr.record_date = #{recordDate}
AND wr.plan_id = #{planId}
ORDER BY wr.record_date DESC, wr.create_time DESC

